package org.jsoup.select;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.parser.TokenQueue;
import org.jsoup.select.Evaluator;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for QueryParser.parse(String query)
 */
public class QueryParser_parse_TriageGen1Test {

    @Test
    public void testParse_SimpleTag() {
        String query = "div";
        Evaluator evaluator = QueryParser.parse(query);
        assertNotNull("Evaluator should not be null", evaluator);
        // Since Evaluator is abstract/interface-based in jsoup, 
        // we verify it returns a valid instance for a simple tag.
        assertTrue(evaluator.toString().contains("tag(div)"));
    }

    @Test
    public void testParse_IdSelector() {
        String query = "#id";
        Evaluator evaluator = QueryParser.parse(query);
        assertNotNull(evaluator);
        assertTrue(evaluator.toString().contains("id(id)"));
    }

    @Test
    public void testParse_ClassSelector() {
        String query = ".className";
        Evaluator evaluator = QueryParser.parse(query);
        assertNotNull(evaluator);
        assertTrue(evaluator.toString().contains("class(className)"));
    }

    @Test
    public void testParse_AttributeSelector() {
        String query = "[attr=value]";
        Evaluator evaluator = QueryParser.parse(query);
        assertNotNull(evaluator);
        assertTrue(evaluator.toString().contains("attr(attr, value)"));
    }

    @Test
    public void testParse_ComplexSelector() {
        String query = "div.className#id[attr=value]";
        Evaluator evaluator = QueryParser.parse(query);
        assertNotNull(evaluator);
    }

    @Test
    public void testParse_DescendantSelector() {
        String query = "div p";
        Evaluator evaluator = QueryParser.parse(query);
        assertNotNull(evaluator);
    }

    @Test
    public void testParse_ChildSelector() {
        String query = "div > p";
        Evaluator evaluator = QueryParser.parse(query);
        assertNotNull(evaluator);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParse_EmptyQuery() {
        // Depending on jsoup version, empty string might throw error or return empty evaluator
        // Most CSS parsers require a non-empty selector for meaningful parsing
        QueryParser.parse("");
    }

    @Test(expected = RuntimeException.class)
    public void testParse_InvalidSyntax() {
        // Providing an invalid selector that breaks the parser logic
        QueryParser.parse("div[attr==value]"); 
    }

    @Test
    public void testParse_WhitespaceHandling() {
        String query = "  div   .class  ";
        Evaluator evaluator = QueryParser.parse(query);
        assertNotNull(evaluator);
    }
}
